/* Regular-season award watch. Scores are transparent game-model estimates. */
const AWARD_RACES=[['mvp','MVP Watch'],['roy','Rookie of the Year'],['dpoy','Defensive Player'],['sixth','Sixth Player']];
let awardRaceTab='mvp';
function awardRaceState(){if(state.awardRaces?.year!==state.year)state.awardRaces={year:state.year,weeks:[]};return state.awardRaces}
function awardRaceRows(day=state.day){
 const games=state.history.filter(g=>g.stage==='Regular season'&&g.day<=day),players=new Map([...state.teams.flatMap(t=>t.roster),...state.free].map(p=>[p.id,p])),map=new Map(),records=state.teams.map(()=>({w:0,l:0}));
 for(const g of games){records[g.winner].w++;records[g.winner===g.a?g.b:g.a].l++;for(const b of g.box){if(b.played===false||!(b.mp>0)||!Number.isInteger(b.playerId))continue;const club=state.teams[g.a].abbr===b.team?g.a:g.b;let r=map.get(b.playerId);if(!r){r={id:b.playerId,name:b.name,club,gp:0,latest:-1,mp:0,gs:0,pts:0,reb:0,ast:0,stl:0,blk:0,tov:0,fgm:0,fga:0,ftm:0,fta:0,orb:0,drb:0,pf:0,oppPts:0,defPoss:0,weekPoints:0,weekGames:0,highWeek:0};map.set(b.playerId,r)}if(g.day>r.latest){r.club=club;r.latest=g.day}r.gp++;for(const k of ['mp','gs','pts','reb','ast','stl','blk','tov','fgm','fga','ftm','fta','orb','drb','pf','oppPts','defPoss'])r[k]=r[k]===null||!Number.isFinite(b[k])?null:r[k]+b[k];if(g.day>day-7){r.weekPoints+=b.pts;r.weekGames++;r.highWeek=Math.max(r.highWeek,b.pts)}}}
 const minGames=Math.max(1,Math.ceil(Math.max(0,...records.map(r=>r.w+r.l))*.5));
 return [...map.values()].filter(r=>r.gp>=minGames).map(r=>{const p=players.get(r.id),prior=(state.statsArchive||[]).some(a=>a.id===r.id&&a.year<state.year&&a.gp>0),drafted=(state.draftHistory||[]).some(h=>h.year===state.year-1&&h.picks.some(x=>x.id===r.id));r.rookie=!!p&&!prior&&(p.bio?.debutYear===state.year||drafted);r.bench=r.gs!==null&&r.gp-r.gs>r.gs;r.record=records[r.club];r.ppg=r.pts/r.gp;r.rpg=r.reb/r.gp;r.apg=r.ast/r.gp;r.spg=r.stl===null?null:r.stl/r.gp;r.bpg=r.blk===null?null:r.blk/r.gp;r.mpg=r.mp/r.gp;r.fgp=r.fgm!==null&&r.fga>0?r.fgm/r.fga:null;r.drtg=r.oppPts!==null&&r.defPoss>0?100*r.oppPts/r.defPoss:null;
 r.eff=['pts','reb','ast','stl','blk','fgm','fga','ftm','fta','tov'].every(k=>r[k]!==null)?(r.pts+r.reb+r.ast+r.stl+r.blk-(r.fga-r.fgm)-(r.fta-r.ftm)-r.tov)/r.gp:null;
 r.score=['pts','fgm','fga','ftm','fta','orb','drb','stl','ast','blk','pf','tov'].every(k=>r[k]!==null)?r.pts+.4*r.fgm-.7*r.fga-.4*(r.fta-r.ftm)+.7*r.orb+.3*r.drb+r.stl+.7*r.ast+.7*r.blk-.4*r.pf-r.tov:null;
 r.defense=r.stl!==null&&r.blk!==null&&r.drb!==null?1.5*r.stl+2*r.blk+.3*r.drb:null;return r});
}
function awardCandidates(type,rows=awardRaceRows()){return rows.filter(r=>(type==='roy'?r.rookie:type==='sixth'?r.bench:true)&&(type==='dpoy'?r.defense:r.score)!==null).sort((a,b)=>(type==='dpoy'?b.defense-a.defense:b.score-a.score)||b.gp-a.gp||a.id-b.id).slice(0,5)}
function awardRaceDay(){if(state.day<=0||state.day%7!==0&&state.day!==seasonLength())return;const data=awardRaceState();if(data.weeks.some(w=>w.day===state.day))return;const rows=awardRaceRows();data.weeks.push({day:state.day,ranks:Object.fromEntries(AWARD_RACES.map(([key])=>[key,awardCandidates(key,rows).map(r=>r.id)]))})}
function awardTrend(type,id,index){const previous=(state.awardRaces?.year===state.year?state.awardRaces.weeks:[]).filter(w=>w.day<state.day).sort((a,b)=>b.day-a.day)[0];if(!previous)return {text:'—',label:'No previous weekly ranking',cls:''};const old=(previous.ranks[type]||[]).indexOf(id);if(old<0)return {text:'NEW',label:'New to the top five since the previous weekly ranking',cls:'award-up'};const delta=old-index;return delta>0?{text:'▲ +'+delta,label:'Up '+delta+' places since previous week',cls:'award-up'}:delta<0?{text:'▼ '+delta,label:'Down '+(-delta)+' places since previous week',cls:'award-down'}:{text:'—',label:'Unchanged from previous week',cls:''}}
function switchAwardRace(key){if(AWARD_RACES.some(([k])=>k===key)){awardRaceTab=key;render()}}
function awardRacesView(){const type=awardRaceTab,rows=awardCandidates(type),final=state.day>=seasonLength(),fmt=n=>n===null||!Number.isFinite(n)?'—':n.toFixed(1),leader=rows[0],title=AWARD_RACES.find(([k])=>k===type)[1],previous=(state.awardRaces?.year===state.year?state.awardRaces.weeks:[]).filter(w=>w.day<state.day).sort((a,b)=>b.day-a.day)[0];const columns=type==='dpoy'?['RPG','BPG','SPG','DRtg']:type==='roy'?['GP','MPG','PPG','RPG','APG','FG%']:['PPG','RPG','APG','EFF'];
 return `<div class="award-page"><section class="panel"><div class="panelhead"><div><div class="eyebrow">${final?'REGULAR SEASON COMPLETE':'WEEK '+Math.max(1,Math.ceil(state.day/7))} · ${escapeHTML(scheduleDateLabel(Math.max(1,Math.min(state.day,seasonLength())),true))}</div><h2>Awards Watch</h2></div><span class="badge">${final?'Final model rankings':'Live projections'}</span></div><div class="award-body"><nav class="po-tabs" aria-label="Award races">${AWARD_RACES.map(([key,label])=>`<button onclick="switchAwardRace('${key}')" class="${type===key?'selected':''}" aria-pressed="${type===key}">${label}</button>`).join('')}</nav>${leader?`<div class="award-spotlight"><div>${secondaryTeamLogo(state.teams[leader.club])}</div><div><div class="eyebrow">${final?'TOP-RANKED CANDIDATE':'FRONTRUNNER'} · ${title}</div><h3><button class="namebutton" onclick="profile(${leader.id})">${escapeHTML(leader.name)}</button></h3><p>${escapeHTML(state.teams[leader.club].city+' '+state.teams[leader.club].name)} · ${leader.record.w}–${leader.record.l}</p><p>${type==='dpoy'?`${escapeHTML(leader.name)} leads this defensive watch with ${fmt(leader.rpg)} rebounds, ${fmt(leader.bpg)} blocks and ${fmt(leader.spg)} steals per game.`:`${escapeHTML(leader.name)} leads the ${title.toLowerCase()} race with ${fmt(leader.ppg)} points, ${fmt(leader.rpg)} rebounds and ${fmt(leader.apg)} assists per game.`} ${leader.weekGames?`Over the last seven calendar days: ${leader.weekPoints} points in ${leader.weekGames} games, including a ${leader.highWeek}-point high.`:''}</p></div></div><div class="award-scroll" tabindex="0" role="region" aria-label="${title} rankings"><table><thead><tr><th>Rank</th><th>Player</th><th>Team</th><th>Record</th>${columns.map(k=>`<th>${k}</th>`).join('')}<th>Impact</th><th>Trend</th></tr></thead><tbody>${rows.map((r,i)=>{const t=state.teams[r.club],trend=awardTrend(type,r.id,i),values=type==='dpoy'?[r.rpg,r.bpg,r.spg,r.drtg]:type==='roy'?[r.gp,r.mpg,r.ppg,r.rpg,r.apg,r.fgp===null?null:r.fgp*100]:[r.ppg,r.rpg,r.apg,r.eff],top=type==='dpoy'?leader.defense:leader.score,score=type==='dpoy'?r.defense:r.score,impact=Math.round(top>0?Math.max(0,Math.min(100,score/top*100)):0);return `<tr class="${i===0?'award-leader':''}"><td>#${i+1}</td><th scope="row"><button class="namebutton" onclick="profile(${r.id})">${escapeHTML(r.name)}</button>${i===0?'<small class="award-label">'+(final?'Top candidate':'Frontrunner')+'</small>':''}</th><td><span class="po-stat-team">${secondaryTeamLogo(t)}${escapeHTML(t.abbr)}</span></td><td>${r.record.w}–${r.record.l}</td>${values.map((v,j)=>`<td>${type==='roy'&&j===0?v:fmt(v)}${type==='roy'&&j===5&&v!==null?'%':''}</td>`).join('')}<td><div class="award-impact"><meter min="0" max="100" value="${impact}" aria-label="${escapeHTML(r.name)} relative impact ${impact} of 100"></meter><span>${impact}</span></div></td><td class="${trend.cls}" title="${trend.label}">${trend.text}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="award-empty"><h3>${state.day?'No eligible candidates yet':'The race starts on opening night'}</h3><p>${type==='roy'?'Rookies need recorded regular-season appearances.':type==='sixth'?'Candidates must have more bench appearances than starts.':'Simulate regular-season games to start the rankings.'}</p></div>`}<p class="muted award-method">${previous?'Movement compares with the saved rankings after day '+previous.day+'.':'Weekly movement appears after a previous weekly ranking is available.'} Impact is relative to this race’s leader, not an attribute rating or voting probability.</p><details class="award-method"><summary>Eligibility & scoring</summary><p>Regular-season games only. Minimum appearances: half the most games played by any team, rounded up. MVP, rookie and sixth-player rankings use cumulative game score, matching the game’s MVP watch model. Defensive rankings use 1.5 × steals + 2 × blocks + 0.3 × defensive rebounds. Ties use games played, then player ID.</p><p>Rookies are first-season players or last draft’s recruits without an earlier recorded season. Sixth Player requires more bench appearances than starts. EFF is box-score efficiency per game. DRtg uses opponent points per 100 on-court defensive possessions; missing tracking shows —. These are simulation projections, not official voting results.</p></details></div></section></div>`;
}
function readAwardRaces(raw,bad){if(raw===undefined)return undefined;if(!raw||!Number.isInteger(raw.year)||raw.year<1900||raw.year>10000||!Array.isArray(raw.weeks)||raw.weeks.length>53)bad('invalid award races');const seen=new Set();return {year:raw.year,weeks:raw.weeks.map(w=>{if(!w||!Number.isInteger(w.day)||w.day<1||w.day>366||seen.has(w.day)||!w.ranks)bad('invalid award week');seen.add(w.day);const ranks={};for(const [key] of AWARD_RACES){const ids=w.ranks[key]??(['mip','coach','executive'].includes(key)?[]:undefined);if(!Array.isArray(ids)||ids.length>5||new Set(ids).size!==ids.length||ids.some(id=>!Number.isInteger(id)||id<0||id>10000000))bad('invalid award ranking');ranks[key]=[...ids]}return {day:w.day,ranks}})}}
